import {replaySample,oppositeSample} from './shift-replay.mjs';
import {mountBike} from './bike-3d.mjs';
import {createShift,shiftState,shiftScore,shiftAct,shiftFaults,shiftHintAvailable,intermittentSweepComplete} from './shift-model.mjs';
const $=s=>document.querySelector(s),storageKey='mecanica.bikes.shifting.v1';let cursor=null,replayTimer=null;let s=createShift(),running=false,exploded=false,rows=[],warning='';try{const data=JSON.parse(localStorage.getItem(storageKey)||'[]');if(Array.isArray(data))rows=data.filter(r=>r&&typeof r.id==='string'&&Number.isFinite(r.score)&&typeof r.date==='string').slice(-30);}catch{warning='No se pudo leer el historial.';}
const info={hanger:'Patilla: fija la geometría del cambio. Una inclinación causa error diferente según corona; se diagnostica con útil de alineación, no doblando a ojo.',shiftCable:'Guaya y funda: el cable necesita deslizar y retornar. El movimiento de la guía depende de desde dónde llegas cuando hay fricción.',cassette:'Siete coronas. La corona resaltada corresponde a la posición más cercana de la guía. Una guía entre coronas indica mala alineación, no un engrane correcto.',chain:'La cadena cambia su línea lateral hacia el cassette. Se representa la trayectoria de forma esquemática; el cambio real necesita giro y contacto con los dientes.',derailleur:'La guía se desplaza con el mando y el tensor, hasta encontrar uno de los topes. Observa su posición respecto a la corona objetivo.',stops:'H (cabeza ámbar, izquierda) y L (cabeza verde, derecha) limitan extremos distintos. El giro visible representa pasos de ajuste; no equivale al sentido ni número de vueltas de tu componente.',frame:'Bicicleta completa sobre el banco. Acerca la transmisión para comprobar la línea de cadena.'};
const bench=mountBike($('#viewport'),focus);
function focus(id){if(!info[id])return;bench.select(id);bench.focus();$('#piece').textContent=info[id];}
function update(){const historic=cursor!==null?replaySample(s.trace,cursor):null,display=historic?.model||s,v=historic?.model||shiftState(s),position=v.position;bench.set({gear:v.teeth,cadence:24,faults:{},shift:{radius:.15+v.engaged*.03,chainZ:.7-position*.075,guideZ:.7-position*.075,h:display.h,l:display.l,b:display.b,hangerAngle:v.hangerAngle,cableDrag:v.cableDrag}});bench.play(cursor===null&&running&&!v.unsafe);$('#play').disabled=cursor!==null;$('#play').textContent=cursor!==null?'Histórico · giro pausado':cursor===null&&running&&!v.unsafe?'Pausar transmisión':v.unsafe?'Ensayo pausado · fuera de rango':'Mover transmisión';$('#play').setAttribute('aria-pressed',String(cursor===null&&running&&!v.unsafe));$('#shiftReadout').textContent=(historic?'HISTÓRICO · maniobra '+historic.sample.move+' · revisión '+historic.sample.revision+' · '+(historic.sample.direction>0?'subiendo':'bajando')+' · marcha '+historic.sample.gear:(s.test==='gear'?'Mando: marcha '+(s.requested+1):'Prueba de extremo '+s.test.toUpperCase()))+' · Guía: posición '+(position+1).toFixed(2)+' / 7 · '+v.status;$('#score').textContent=shiftScore(s)+'/100';$('#feedback').textContent=s.feedback;$('#checks').textContent=['h','l','b','hanger','cable',...Array.from({length:7},(_,i)=>'g'+i)].map(k=>(k[0]==='g'?+k.slice(1)+1:({h:'H',l:'L',b:'B',hanger:'Patilla',cable:'Guaya'}[k]||k))+': '+(s.checks[k]===true?'✓':s.checks[k]===false?'✕':'pendiente')).join(' · ');for(const b of $('#gears').children){b.disabled=s.done||cursor!==null;b.setAttribute('aria-pressed',String(display.test==='gear'&&+b.dataset.gear===display.requested));}for(const b of $('#adjustments').querySelectorAll('button'))b.disabled=s.done||cursor!==null;for(const id of ['testH','testL','testB','testHanger','testCable','repairHanger','repairCable','verify'])$('#'+id).disabled=s.done||cursor!==null;$('#hint').disabled=cursor!==null||!shiftHintAvailable(s);
 for(const key of ['trim','h','l','b']){const original=s.initial[{trim:0,h:1,l:2,b:3}[key]],delta=Math.round((s[key]-original)*10);$('#delta-'+key).textContent='Cambio aplicado desde el inicio: '+(delta>=0?'+':'')+delta+' pasos';}
 if(s.done&&!rows.some(r=>r.id===s.id)){rows.push({id:s.id,date:new Date().toISOString(),score:shiftScore(s),mode:s.mode,errors:s.errors,hints:s.hints,causes:s.causes,events:structuredClone(s.events),trace:structuredClone(s.trace),passes:structuredClone(s.passes)});rows=rows.slice(-30);try{localStorage.setItem(storageKey,JSON.stringify(rows));}catch{warning='El resultado solo se conserva en esta sesión.';}}
 $('#result').replaceChildren();if(s.done){add('h3','Caso resuelto', $('#result'));add('p','Causas iniciales: '+s.causes.map(k=>shiftFaults[k]).join(' · '),$('#result'));add('p','Separa geometría, fricción y ajuste: mide patilla y cable, comprueba B y topes, y después afina la indexación. El tensor no corrige una patilla doblada ni libera una guaya atascada. La sustitución de patilla del modelo no enseña a enderezar piezas a mano.', $('#result'));if(s.mode==='intermittent'){const before=s.trace.filter(t=>t.revision<s.revision&&t.drag).length;add('p','En las muestras conservadas se registraron '+before+' episodios de resistencia antes de la reparación. Después se completaron dos recorridos de subida y bajada sin desalineación. Que una maniobra saliera bien antes de reparar no descartaba la avería.',$('#result'));}if(s.mode==='combined'){const useful=s.events.filter(e=>e.repair&&e.good);for(const e of useful)add('p',(e.repair==='hanger'?'Tras corregir patilla':'Tras liberar la guaya')+': '+(e.remaining?.length?'seguían pendientes '+e.remaining.map(f=>shiftFaults[f]).join(', '):'sin causas iniciales pendientes')+'.',$('#result'));}}renderTrace();renderHistory();}
function act(action,key,value){if(cursor!==null)return;shiftAct(s,action,key,value);update();}
function add(tag,text,root){const e=document.createElement(tag);e.textContent=text;root.append(e);return e;}
for(let i=0;i<7;i++){const b=add('button',String(i+1),$('#gears'));b.dataset.gear=i;b.setAttribute('aria-label','Seleccionar marcha '+(i+1));b.onclick=()=>act('select',null,i);}
const specs=[['b','Ajuste B · separación de roldana','Controla la separación de la roldana guía al cassette. El objetivo 1,0 es relativo: no representa milímetros ni una especificación universal.','Acercar roldana','Alejar roldana'],['trim','Tensor · indexación','Alinea las marchas intermedias. No modifica los topes físicos.','Reducir tensión','Aumentar tensión'],['h','Tope H · corona pequeña','Debe permitir llegar a la corona pequeña sin dejar salir la cadena hacia afuera.','Permitir más salida exterior','Limitar salida exterior'],['l','Tope L · corona grande','Debe permitir alcanzar la corona grande sin dejar pasar hacia los radios.','Limitar hacia los radios','Permitir más recorrido interior']];
for(const [key,title,copy,minus,plus]of specs){const card=add('div','',$('#adjustments'));card.className='adjustment';add('h3',title,card);add('p',copy,card);for(const [label,value]of [[minus,-1],[plus,1]]){const b=add('button',label,card);b.dataset.adjust=key;b.dataset.direction=value;b.onclick=()=>act('adjust',key,value);}const d=add('p','',card);d.id='delta-'+key;d.className='caption';}
function start(mode){stopReplay();cursor=null;s=createShift(mode);running=false;instructions();update();focus('cassette');}
function instructions(){const root=$('#instructions');root.replaceChildren();add('h2',s.mode==='guided'?'Taller guiado · topes e indexación':s.mode==='combined'?'Fallos combinados · separa las causas':s.mode==='intermittent'?'Guaya intermitente · captura el episodio':'Fallo sorpresa · mide antes de ajustar',root);if(s.mode==='guided'){const ol=add('ol','',root);ol.className='guided-steps';for(const t of ['Inspecciona la separación B, la alineación de patilla y el deslizamiento del cable.','Prueba H con el cable aislado y alinea la guía con la corona 1.','Prueba L y alinea el extremo interior con la corona 7.','Selecciona una marcha intermedia. Ajusta tensión en pequeños pasos para alinear la guía.','Recorre las siete marchas y repite H/L, B, patilla y cable después del último ajuste.','Comprueba el trabajo completo y consulta las causas al terminar.'])add('li',t,ol);}else if(s.mode==='intermittent'){add('p','Recorre 1→7→1 varias veces. El atasco aparece por maniobras, no por tiempo de reloj; volver a pulsar la misma marcha no genera una muestra nueva. Usa el registro para comparar sentido, posición y error. Una inspección normal no descarta el fallo.',root);add('p','Después de reparar: dos pasadas completas de subida y bajada, más las comprobaciones H/L, B, patilla y guaya. Las pistas cuestan 10 puntos; una pista para diagnosticar y otra para la verificación final.',root);}else if(s.mode==='combined'){add('p','Este caso combina '+s.causes.length+' causas. La lista inicial se revela al terminar; usa las pruebas para descubrir cada causa. Un síntoma puede ocultar otro: mide patilla, prueba retorno de guaya y revisa B y topes. Tras una corrección, compara qué cambió y qué persiste.',root);add('p','Pistas: una por causa pendiente priorizada, −10 cada una. Tras resolver esa causa se desbloquea la siguiente; repetir una pista no vuelve a descontar. La puntuación nunca baja de 0.',root);}else add('p','Puede fallar la indexación, H/L, la separación B, la patilla o el deslizamiento del cable. Compara la misma marcha al subir y al bajar; mide la patilla si el error cambia entre coronas. Un extremo demasiado abierto puede parecer correcto al cambiar de marcha: comprueba también sus límites.',root);}
function stopReplay(){if(replayTimer!==null)clearInterval(replayTimer);replayTimer=null;}
function preview(i,focusCursor=false){stopReplay();if(!replaySample(s.trace,i))return;cursor=i;update();if(focusCursor)$('#traceCursor')?.focus({preventScroll:true});}
function live(){stopReplay();cursor=null;update();}
function renderTrace(){const root=$('#trace');root.replaceChildren();root.hidden=s.mode!=='intermittent';if(root.hidden)return;add('h3','Registro y cursor histórico',root);const jump=add('a','Ver la maniobra en el banco 3D ↑',root);jump.href='#banco';add('p','Hasta 120 maniobras conservadas. El histórico muestra el estado guardado y bloquea ajustes: no cambia puntuación, pruebas ni la avería actual. La reproducción avanza una maniobra cada 1,5 s; no representa tiempos reales.',root);
 const up=[1,2,3,4,5,6].filter(g=>(s.passes['up'+g]||0)>=2).length,down=[0,1,2,3,4,5].filter(g=>(s.passes['down'+g]||0)>=2).length;add('p','Estado actual: '+up+'/6 destinos de subida y '+down+'/6 de bajada con dos aciertos. '+(intermittentSweepComplete(s)?'Barridos completos.':'Continúa recorriendo 1→7→1, una marcha por paso.'),root);
 if(!s.trace.length){add('p','Selecciona una marcha distinta para empezar a registrar.',root);return;}
 const label=add('label','Cursor de maniobra',root);label.htmlFor='traceCursor';const slider=add('input','',root);slider.type='range';slider.id='traceCursor';slider.min=0;slider.max=s.trace.length-1;slider.value=cursor??s.trace.length-1;slider.style.maxWidth='100%';slider.style.width='100%';slider.setAttribute('aria-valuetext',cursor===null?'En vivo; mueve el cursor para revisar':'Maniobra '+s.trace[cursor].move);slider.oninput=()=>preview(+slider.value,true);
 const buttons=add('div','',root);buttons.className='buttons';const button=(label,fn,disabled=false)=>{const b=add('button',label,buttons);b.onclick=fn;b.disabled=disabled;return b;};
 button('Anterior',()=>preview((cursor??s.trace.length)-1),cursor===0).id='tracePrev';button('Siguiente',()=>preview((cursor??-1)+1),cursor===s.trace.length-1).id='traceNext';button('Volver en vivo',live,cursor===null).id='traceLive';
 button(replayTimer===null?'Reproducir pasos':'Pausar reproducción',()=>{if(replayTimer!==null){stopReplay();update();return;}if(cursor===null||cursor===s.trace.length-1)cursor=0;replayTimer=setInterval(()=>{if(document.hidden){stopReplay();update();return;}if(cursor>=s.trace.length-1){stopReplay();update();return;}cursor++;if(cursor===s.trace.length-1)stopReplay();update();},1500);update();}).id='tracePlay';
 if(cursor!==null){const t=s.trace[cursor],other=oppositeSample(s.trace,cursor);add('p','Revisando maniobra '+t.move+' · '+(t.direction>0?'subida':'bajada')+' · error '+t.error.toFixed(2)+' · '+(t.drag?'resistencia de guaya presente':'guaya libre en esa maniobra')+'.',root);if(other>=0){const o=s.trace[other];add('p','Misma marcha '+t.gear+', misma revisión '+t.revision+': aquí '+t.error.toFixed(2)+'; en sentido opuesto '+o.error.toFixed(2)+' (maniobra '+o.move+'). Una diferencia aislada también puede deberse a la fase intermitente; compara varias muestras.',root);button('Comparar sentido opuesto',()=>preview(other)).id='traceOpposite';}else add('p','No hay muestra de esta marcha en sentido opuesto dentro de la misma revisión. Registra otra pasada en vivo.',root);}
 const table=add('table','',root);table.className='trace-table';const head=add('tr','',add('thead','',table));for(const title of ['Paso / revisión','Marcha / sentido','Error de guía','Lectura'])add('th',title,head).scope='col';const body=add('tbody','',table),first=cursor===null?Math.max(0,s.trace.length-12):Math.floor(cursor/12)*12;for(let i=first;i<Math.min(first+12,s.trace.length);i++){const t=s.trace[i],row=add('tr','',body);if(i===cursor)row.className='trace-selected';const cell=add('td','',row),b=add('button',t.move+' / '+t.revision,cell);b.dataset.traceIndex=i;b.setAttribute('aria-label','Revisar maniobra '+t.move);b.setAttribute('aria-pressed',String(i===cursor));b.onclick=()=>preview(i);add('td',t.gear+' / '+(t.direction>0?'↑ sube':'↓ baja'),row);add('td',(t.error>=0?'+':'')+t.error.toFixed(2),row);add('td',t.aligned?'Alineada':'Desalineada',row);}}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&replayTimer!==null){stopReplay();update();}});
function renderHistory(){const root=$('#history');root.replaceChildren();add('h2','Tus prácticas de cambios',root);if(warning)add('p',warning,root);if(!rows.length)add('p','Los resultados aparecerán al completar la verificación. Se guardan hasta 30 casos en este navegador.',root);else{const ul=add('ul','',root);for(const r of rows.slice(-5).reverse())add('li',new Date(r.date).toLocaleDateString('es-CO')+' · '+(r.mode==='guided'?'Guiado':r.mode==='combined'?'Combinado':r.mode==='intermittent'?'Intermitente':'Sorpresa')+' · '+r.score+'/100 · '+r.errors+' errores · '+r.hints+' pistas',ul);}}
$('#guided').onclick=()=>start('guided');$('#surprise').onclick=()=>start('surprise');$('#combined').onclick=()=>start('combined');$('#intermittent').onclick=()=>start('intermittent');$('#testH').onclick=()=>act('test','h');$('#testL').onclick=()=>act('test','l');$('#testB').onclick=()=>{act('inspect','b');focus('derailleur');};$('#testHanger').onclick=()=>{act('inspect','hanger');focus('hanger');};$('#testCable').onclick=()=>{act('inspect','cable');focus('shiftCable');};$('#repairHanger').onclick=()=>act('repair','hanger');$('#repairCable').onclick=()=>act('repair','cable');$('#hint').onclick=()=>act('hint');$('#verify').onclick=()=>act('verify');$('#play').onclick=()=>{running=!running;update();};$('#explode').onclick=()=>{exploded=!exploded;bench.explode(exploded);$('#explode').setAttribute('aria-pressed',String(exploded));$('#explode').textContent=exploded?'Ensamblar':'Despiece';};$('#overview').onclick=()=>bench.reset();document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>focus(b.dataset.part));instructions();update();focus('cassette');window.shiftDebug=()=>({state:s,model:shiftState(s),bench:bench.debug?.(),history:rows,cursor,replaying:replayTimer!==null});
